etc/fr_os/applied-config.yaml.text:
version: 1
hostname: fr-router
interfaces:
  wan: {device: eth0, zone: wan}
  lan: {device: eth1, zone: lan, address: 10.0.0.1/24}
zones: {wan: {}, lan: {}, vpn: {}}
rules:
