flush ruleset

table inet fr_os {
	set lan_ifaces {
		type ifname
		elements = { "lo" }
	}
	set vpn_ifaces {
		type ifname
		elements = { "wg0" }
	}
	set wan_ifaces {
		type ifname
		elements = { "eth0" }
	}

	set bruteforce_jail {
		type ipv4_addr
		flags timeout
	}
	set bruteforce_jail6 {
		type ipv6_addr
		flags interval, timeout
	}
	set bruteforce_jail_mac {
		type ether_addr
		flags timeout
	}

	set ids_quarantine {
		type ipv4_addr
		flags timeout
	}
	set ids_quarantine_mac {
